@js:
const host = cleanHost();
const list = [];
const push = (title, typeId, size) => {
	 const tag = title == "全部" ? "" : title;
  list.push({
    title,
    url: host + "/api/cate/,"+ JSON.stringify({
        "method": "POST",
        "body": `{"page":{"page":{{page}},"pageSize":36},"category":"video","sort":0,"comic":{"status":-1,"day":0,"year":0,"tag":""},"video":{"year":0,"typeId":${typeId},"area":"","lang":"","status":-1,"tag":"${tag}"},"novel":{"status":-1,"day":0,"sortId":0}}`,
        "headers": {
          "Content-Type": "application/json",
          "X-Requested-With": "XMLHttpRequest",
          "User-Agent": "Mozilla/5.0 (Linux; Android 16; 25102RKBEC Build/BP2A.250605.031.A3) AppleWebKit/537.36 (KHTML, like Gecko) Version/4.0 Chrome/143.0.7499.192 Mobile Safari/537.36",
          "Referer": host + "/cate/"
        }
    }),
    style: {
        layout_flexGrow: 1,
        layout_flexBasisPercent: size
    }
  })
};

// 分类
const types = ["全部", "国产", "日韩", "欧美", "港台", "电影", "里番"];
// tag列表
const tags = ["全部", "动画", "喜剧", "奇幻", "剧情", "冒险", "动作", "科幻", "爱情", "儿童", "短片", "家庭", "悬疑", "运动"];

const type = infoMap["分类"] || types[0];
const typeId = types.findIndex(t => t == type);

list.push({
	 title: "分类",
	 type: "select",
	 action: "java.refreshExplore()",
	 chars: types,
	 default: type,
	 style: {layout_flexBasisPercent: 1}
})

tags.forEach(tag => push(tag, typeId, 0.29))

JSON.stringify(list);

